'use strict';
const $ = (s, root = document) => root.querySelector(s);
const main = $('#main');
const tours = [
  {id:'mozambique',title:'The Mozambique escape',location:'Maputo & Bilene · Mozambique',category:'Beach & islands',price:8700,image:9,source:'mozambique-travel-package',duration:'4 nights',date:'Ask for the next departure',description:'Beach days, a taste of Maputo and the beautiful waters of Bilene. A coastal escape with plenty to explore.',included:['Transportation','1 night in Maputo and 3 nights in Bilene','Breakfasts in Maputo and Bilene','Lunch at Teka Famba','Koko Beach, snorkeling and quad biking','Boat cruise, Xai Xai Beach and Maputo tour'],note:'The published 2026 departures have passed. Ask the team about the next available trip.'},
  {id:'cape-town',title:'Cape Town, beautifully explored',location:'Cape Town · South Africa',category:'City & culture',price:13900,image:4,source:'cape-town-travel-package',duration:'22–26 October 2026',date:'22–26 October 2026 · confirm availability',description:'Coastal views, iconic landmarks and the Cape Winelands. Discover a different side of the Mother City.',included:['Accommodation, road transport and flights','Breakfast','Cape Point and Robben Island','Boat cruise and Penguin Colony','Beyerskloof and Simonsig wine tastings','Table Mountain and Red Tour Bus','Dinner at Utopia'],note:'The Dunes activity is listed at your own cost. Confirm departure details, seat availability and all inclusions with Travel Saki.'},
  {id:'namibia',title:'Where desert meets ocean',location:'Windhoek & Swakopmund · Namibia',category:'Adventure',price:15900,image:10,source:'namibia-adventure-package',duration:'4 nights',date:'Ask for the next departure',description:'Wide-open landscapes, coastal adventures and time to explore Namibia’s capital and Swakopmund.',included:['Return flights from OR Tambo to Windhoek','Tour of Windhoek and transport in Namibia','1 night in Windhoek and 3 nights in Swakopmund','4 breakfasts and 4 dinners','Boat cruise, quad biking and Pink Salt Lake'],note:'Camel riding, kayaking, sandboarding, skydiving and the 4×4 experience are listed at your own cost. Published departures have passed; request new dates.'},
  {id:'zanzibar',title:'Zanzibar, at your own pace',location:'Stone Town, Pingwe & Matemwe · Tanzania',category:'Beach & islands',price:28900,image:13,source:'zanzibar-travel-package',duration:'6 nights',date:'Ask for the next departure',description:'Island scenery, Stone Town discoveries and warm-water adventures across three Zanzibar stays.',included:['2 nights each in Stone Town, Pingwe and Matemwe','Return flights, accommodation and transport in Zanzibar','Breakfast and dinner','Stone Town, Night Market and Spice Farm tours','Prison Island and Nakupenda boat trip with lunch','Salaam caves, snorkeling and a sunset dhow experience'],note:'Other activities may be at your own cost. Published departure wording is unclear and has passed; the team must confirm a new itinerary and dates.'},
  {id:'mauritius',title:'A little Mauritius magic',location:'Mauritius · Indian Ocean',category:'Beach & islands',price:28800,image:8,source:'mauritius-getaway',duration:'6 nights',date:'Ask for the next departure',description:'A tropical island journey with beach time, local discoveries and a slower rhythm.',included:['Flights, airport transfer and accommodation','6 breakfasts and 6 dinners','Le Morne Beach and Chamarel','Port Louis market and Casela Nature Park','Catamaran cruise and island activities as listed'],note:'Some optional activities are listed at your own cost. Ask for the next departure and a confirmed list of included activities.'},
  {id:'sun-city',title:'Sun City meets the wild',location:'Sun City & Pilanesberg · South Africa',category:'Safari & nature',price:2500,image:11,source:'sun-city-pilanesberg-game-drive-package',duration:'1 day · choose your dates',date:'Choose your dates · subject to availability',description:'A day of waterpark fun and wildlife discovery, with return transport arranged from Gauteng.',included:['Return transport from Johannesburg, Midrand or Pretoria','Entrance to Sun City, Valley of Waves and slides','R100 meal voucher','Pilanesberg game drive'],note:'Travel Saki lists this as a one-day package. Confirm your preferred date, pickup point and availability before booking.'},
  {id:'hazyview',title:'Your gateway to a safari',location:'Hazyview · Mpumalanga',category:'Safari & nature',price:4750,image:7,source:'hazyview-mpumalanga-travel-package',duration:'Tailored safari enquiry',date:'Ask for departure dates',description:'Discover Mpumalanga and start planning a safari experience with the Travel Saki team.',included:[],note:'Request the current itinerary, duration, inclusions and exclusions from the team.'},
  {id:'dubai',title:'A different kind of Dubai',location:'Dubai · United Arab Emirates',category:'City & culture',price:36950,image:5,source:'dubai-travel-package',duration:'Ask for the itinerary',date:'Ask for departure dates',description:'Big-city energy and memorable discoveries. Explore Travel Saki’s published Dubai package.',included:[],note:'Ask the team to confirm travel dates, visa requirements, itinerary and all package inclusions.'},
  {id:'afriski',title:'Snow days at Afriski',location:'Afriski · Lesotho',category:'Adventure',price:2700,image:3,source:'afriski-snow-adventure-package',duration:'Seasonal travel',date:'Ask for seasonal departures',description:'Swap your usual escape for mountain air and an adventure in Lesotho’s highlands.',included:[],note:'Snow conditions are seasonal. Confirm dates, border requirements and the current itinerary with Travel Saki.'},
  {id:'clarens',title:'Afriski & Clarens',location:'Lesotho & Free State',category:'Adventure',price:5500,image:2,source:'afriski-clarens-travel-package',duration:'Ask for the itinerary',date:'Ask for seasonal departures',description:'A mountain escape combining the Afriski highlands with the charm of Clarens.',included:[],note:'Confirm seasonal availability, travel documents and all package details with the team.'},
  {id:'three-countries',title:'Three countries. New flavours.',location:'Mpumalanga, Eswatini & Maputo',category:'City & culture',price:6500,image:1,source:'mpumalanga-swaziland-maputo-experience',duration:'Ask for the itinerary',date:'Ask for departure dates',description:'Explore Travel Saki’s published three-country dining experience and plan a journey around discovery.',included:[],note:'Ask the team for a confirmed route, travel dates, border requirements and inclusions.'}
];
const categories = ['All experiences','Beach & islands','Safari & nature','Adventure','City & culture'];
const currency = n => 'R ' + n.toLocaleString('en-ZA');
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved = [];
try { saved = JSON.parse(localStorage.getItem('travel-saki-saved') || '[]'); if (!Array.isArray(saved)) saved = []; } catch { saved = []; }
let currentFilters = {query:'', category:'All experiences', sort:'featured', savedOnly:false};
let homeCategory = 'All experiences';
let preferredMonth = ''; 
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function saveTour(id){saved = saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('travel-saki-saved',JSON.stringify(saved));}catch{}document.querySelectorAll(`[data-save="${id}"]`).forEach(b=>{b.setAttribute('aria-pressed',saved.includes(id));b.innerHTML=(saved.includes(id)?'♥':'♡')+(b.classList.contains('save')?'':' Save to shortlist');b.setAttribute('aria-label',(saved.includes(id)?'Remove saved ':'Save ')+tours.find(t=>t.id===id).title);});toast(saved.includes(id)?'Experience saved to your shortlist':'Experience removed from your shortlist');if(currentFilters.savedOnly && location.hash.startsWith('#tours'))updateTours();}
function tourCard(t){return `<article class="tour-card"><div class="card-image"><img src="assets/package-${t.image}.webp" alt="${esc(t.title)} — photography from Travel Saki" loading="lazy"><span class="tag">${esc(t.category)}</span><button class="save" data-save="${t.id}" aria-pressed="${saved.includes(t.id)}" aria-label="${saved.includes(t.id)?'Remove saved':'Save'} ${esc(t.title)}">${saved.includes(t.id)?'♥':'♡'}</button></div><div class="card-body"><div class="card-location">${esc(t.location)}</div><h3>${esc(t.title)}</h3><p>${esc(t.duration)}</p><div class="card-foot"><div class="price">${currency(t.price)}<small>Published package price</small></div><button class="round-link" data-detail="${t.id}" aria-label="View ${esc(t.title)} details">↗</button></div></div></article>`;}
function priceNote(){return '<p class="disclaimer">Prices are taken from Travel Saki’s published catalogue. New departure dates, pricing, inclusions and availability must be confirmed with the team. This website does not confirm bookings or take payments.</p>';}
function cta(){return `<section class="cta-banner"><div><span class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h2>Somewhere new. <i>Something unforgettable.</i></h2><p>Tell us where you dream of going. We’ll help with the details.</p></div><a href="#plan" class="button">Let’s plan your trip ↗</a></section>`;}
function home(){return `<section class="hero reveal"><div class="hero-copy"><span class="eyebrow">AFRICAN ADVENTURES & ISLAND ESCAPES</span><h1>Your next<br>great <i>escape.</i></h1><p>From safari to sea, make room for a little more wonder. Personal journeys, good company and the details taken care of.</p><div class="hero-actions"><a href="#tours" class="button">Explore our tours ↗</a><a href="#plan" class="text-link">Make it your own ↗</a></div></div><div class="hero-photo"><img src="assets/hero-original.webp" alt="Travel Saki travellers enjoying a quad biking adventure in Zanzibar" fetchpriority="high"><div class="photo-stamp">LESS PLANNING<br>MORE<br>MEMORIES ↗</div><div class="photo-caption"><span>A LITTLE ISLAND FREEDOM<br><b>This could be you.</b></span><span>Zanzibar, Tanzania ↗</span></div></div></section><div class="wrap"><form class="searchbar" id="discovery-form"><label><span>WHERE TO?</span><select name="destination" aria-label="Choose destination"><option value="">Anywhere that inspires me</option><option>Mozambique</option><option>Cape Town</option><option>Namibia</option><option>Zanzibar</option><option>Mauritius</option><option>Sun City</option><option>Hazyview</option><option>Dubai</option><option>Afriski</option></select></label><label><span>YOUR KIND OF ESCAPE</span><select name="style" aria-label="Travel style"><option value="All experiences">A little bit of everything</option>${categories.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></label><label><span>WHEN WOULD YOU GO?</span><input type="month" name="month" aria-label="Preferred travel month" min="${new Date().toISOString().slice(0,7)}"></label><button class="button" type="submit">Find my escape ↗</button></form><div class="intro-strip"><span><b>✧</b> Tailored to the way you travel</span><span><b>↗</b> Leisure, group & corporate journeys</span><span><b>⌖</b> Based in Randburg, exploring beyond</span></div></div><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">THE WORLD IS CALLING</span><h2>Go where you<br><i>feel something.</i></h2></div><p>Salt in the air. Sand under your feet. A story you haven’t lived yet. Find an experience that feels like you.</p></div><div class="tabs" id="home-tabs">${categories.map(c=>`<button data-home-category="${esc(c)}" aria-pressed="${c===homeCategory}">${esc(c)}</button>`).join('')}</div><div class="tour-grid" id="home-tour-grid">${homeTourCards()}</div>${priceNote()}<div class="center more"><a class="button outline" href="#tours">Discover all experiences ↗</a></div></div></section><section class="story-band"><div class="image"><img src="assets/activity-2.webp" loading="lazy" alt="A giraffe photographed on a Travel Saki safari"></div><div class="copy"><span class="eyebrow">PERSONAL TRAVEL. REAL CONNECTION.</span><h2>We plan the details.<br>You live <i>the moments.</i></h2><p>A family holiday, a friends’ getaway or a journey for your whole team. Travel Saki brings travel, tours and transport together around the experience you want to have.</p><div class="mini-features"><span>Flights &<br>accommodation</span><span>Transfers &<br>group transport</span><span>Experiences &<br>personal itineraries</span></div><a class="button light" href="#plan">Build your own journey ↗</a></div></section><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">NOT JUST A PLACE. A FEELING.</span><h2>Make the most<br>of <i>being there.</i></h2></div><p>From a quiet cruise to a little adrenaline, let your interests shape the journey.</p></div><div class="activity-grid">${[{image:2,title:'Into the wild',text:'Safari & wildlife',style:'Safari & nature'},{image:3,title:'Take the slow route',text:'Boat cruises & coastal moments',style:'Beach & islands'},{image:4,title:'Find your adventure',text:'Dunes, bikes & open skies',style:'Adventure'},{image:6,title:'Discover the local story',text:'Landmarks, flavours & culture',style:'City & culture'}].map(a=>`<button class="activity" data-experience="${a.style}"><img src="assets/activity-${a.image}.webp" alt="${a.text} with Travel Saki" loading="lazy"><h3>${a.title} ↗</h3><p>${a.text}</p></button>`).join('')}</div></div></section><section class="section" style="padding-top:0"><div class="wrap journey"><div class="portrait"><img src="assets/founder.webp" alt="Isaac ‘Saki’ Komane, founder of Travel Saki" loading="lazy"><div class="quote-box"><p>A familiar destination.<br>A completely new experience.</p><span>THE TRAVEL SAKI PHILOSOPHY</span></div></div><div class="journey-copy"><span class="eyebrow">MEET THE PERSON BEHIND THE JOURNEY</span><h2>A love for travel.<br><i>A personal touch.</i></h2><p>Isaac ‘Saki’ Komane started Travel Saki in 2018, turning a passion for planning group trips into journeys for other people. The idea remains simple: make the experience personal, memorable and easier to enjoy.</p><div class="steps"><div><b>01</b><h3>Tell us your dream</h3><p>Your people, dates and travel style.</p></div><div><b>02</b><h3>Shape the journey</h3><p>A plan built around what matters to you.</p></div><div><b>03</b><h3>Make new memories</h3><p>Confirm your trip and enjoy the experience.</p></div></div><a class="text-link" href="#about">Meet Travel Saki ↗</a></div></div></section>${cta()}<section class="section"><div class="wrap"><div class="social-header"><div><span class="eyebrow">OUT THERE, TOGETHER</span><h2>A few moments <i>worth keeping.</i></h2><p>Real trip photographs from Travel Saki. Follow along for their latest adventures.</p></div><div class="social-links"><a class="text-link" href="https://www.instagram.com/travelsaki_sa/" target="_blank" rel="noopener noreferrer">Instagram ↗</a><a class="text-link" href="https://www.facebook.com/Travelsakisa/" target="_blank" rel="noopener noreferrer">Facebook ↗</a></div></div><div class="social-gallery">${['hero-original','package-1','activity-3','activity-4','package-12'].map((f,i)=>`<img src="assets/${f}.webp" alt="Travel Saki travel memory ${i+1}" loading="lazy">`).join('')}</div></div></section>`;}
function homeTourCards(){const list=homeCategory==='All experiences'?tours.slice(0,3):tours.filter(t=>t.category===homeCategory).slice(0,3);return list.map(tourCard).join('');}
function heading(label,title,description){return `<div class="page-heading"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${description}</p></div>`;}
function toursPage(){return `<div class="wrap page-shell reveal">${heading('FIND YOUR KIND OF JOURNEY','Good places.<br><i>Great possibilities.</i>','Explore Travel Saki’s published travel experiences. Discover the places, compare the options and talk to the team about making one your own.')}<div class="filter-row"><input id="tour-query" type="search" placeholder="Search destinations or experiences" aria-label="Search tours" value="${esc(currentFilters.query)}"><select id="tour-category" aria-label="Filter by experience">${categories.map(c=>`<option ${currentFilters.category===c?'selected':''}>${c}</option>`).join('')}</select><select id="tour-sort" aria-label="Sort tours"><option value="featured">Featured first</option><option value="price-low" ${currentFilters.sort==='price-low'?'selected':''}>Price: low to high</option><option value="price-high" ${currentFilters.sort==='price-high'?'selected':''}>Price: high to low</option><option value="name" ${currentFilters.sort==='name'?'selected':''}>Name: A–Z</option></select></div><div class="results-info"><span id="result-count"></span><button id="saved-filter" class="text-link" style="background:none;border-width:0 0 1px;cursor:pointer" aria-pressed="${currentFilters.savedOnly}">${currentFilters.savedOnly?'Show all experiences':'My shortlist ♡'}</button></div><div id="tour-results" class="tour-grid"></div>${priceNote()}</div>${cta()}`;}
function updateTours(){let list=tours.filter(t=>(currentFilters.category==='All experiences'||t.category===currentFilters.category)&&(!currentFilters.savedOnly||saved.includes(t.id))&&`${t.title} ${t.location} ${t.category}`.toLowerCase().includes(currentFilters.query.toLowerCase()));if(currentFilters.sort==='price-low')list.sort((a,b)=>a.price-b.price);if(currentFilters.sort==='price-high')list.sort((a,b)=>b.price-a.price);if(currentFilters.sort==='name')list.sort((a,b)=>a.title.localeCompare(b.title));$('#result-count').textContent=`${list.length} experience${list.length===1?'':'s'}${currentFilters.savedOnly?' in your shortlist':''}${preferredMonth?' · Preferred month: '+preferredMonth:''}`;$('#tour-results').innerHTML=list.length?list.map(tourCard).join(''):`<div class="empty"><h3>${currentFilters.savedOnly?'Your next adventure is waiting.':'Let’s find something that fits.'}</h3><p>${currentFilters.savedOnly?'Tap a heart on an experience to save it here.':'Try another destination or ask us to tailor a trip for you.'}</p><button class="button outline" data-reset>Show all experiences ↗</button></div>`;}
function destinations(){return `<div class="wrap page-shell reveal">${heading('A WORLD OF POSSIBILITY','Somewhere you’ve dreamed of.<br><i>Somewhere you’ll love.</i>','From South African favourites to island horizons and adventures beyond. Choose a destination and explore the published trips.')}<div class="destination-grid">${[{name:'Mozambique',text:'Maputo discoveries & Bilene beach days',img:9,q:'Mozambique'},{name:'Cape Town',text:'Coastal views, culture & the Winelands',img:4,q:'Cape Town'},{name:'Namibia',text:'Open landscapes & coastal adventure',img:10,q:'Namibia'},{name:'Zanzibar',text:'Island escapes & Stone Town stories',img:13,q:'Zanzibar'},{name:'Mauritius',text:'Slow island days & tropical discoveries',img:8,q:'Mauritius'},{name:'Safari country',text:'Sun City, Pilanesberg & Mpumalanga',img:11,q:'',style:'Safari & nature'},{name:'Lesotho & Clarens',text:'Highland air & seasonal adventures',img:3,q:'Afriski'},{name:'Dubai',text:'City lights & a different horizon',img:5,q:'Dubai'}].map(d=>`<a class="destination" href="#tours?destination=${encodeURIComponent(d.q)}${d.style?'&style='+encodeURIComponent(d.style):''}"><img src="assets/package-${d.img}.webp" alt="${esc(d.name)} — from Travel Saki’s travel photography" loading="lazy"><div><h3>${d.name}</h3><p>${d.text}</p><span class="dest-arrow" aria-hidden="true">↗</span></div></a>`).join('')}</div></div>${cta()}`;}
function transport(){return `<div class="wrap page-shell reveal">${heading('FROM HERE TO THERE, MADE EASIER','The journey matters.<br><i>Every part of it.</i>','Airport transfers, private transport, group outings and long-distance travel. Tell us your route and let Travel Saki help arrange the journey.')}<div class="transport-intro"><img src="assets/package-10.webp" alt="Travel Saki travellers exploring Windhoek" loading="lazy"><div><span class="eyebrow">TRAVEL, TOURS & TRANSPORT</span><h2>Your people.<br>Your plans.<br><i>Your way there.</i></h2><p>Whether you’re moving a team, heading to the airport or planning a weekend away, the right transport helps the experience come together.</p><a class="button" href="#plan?type=Transport">Request a transport quote ↗</a></div></div><div class="service-list">${[['Airport transfers','Arrange your pickup or drop-off. Share your airport, flight time, passenger count and luggage needs.'],['Group & private transport','Bring your friends, family or event guests together with transport planned around your schedule.'],['City-to-city travel','Plan a long-distance journey between major South African cities for yourself or your group.'],['Private chauffeur','Request a private driver for the itinerary, meetings or occasions you have in mind.'],['Business & corporate travel','Coordinate transport for meetings, conferences, events and company getaways.'],['Adventure & leisure trips','Arrange the transport that connects your stay, activities and the places you want to explore.']].map((s,i)=>`<article class="service-row"><span>0${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p><a class="button outline compact" href="#plan?type=Transport&service=${encodeURIComponent(s[0])}">Enquire ↗</a></article>`).join('')}</div><p class="disclaimer">Vehicles, pickup times, route availability and prices are confirmed by the team when preparing your quote.</p></div>${cta()}`;}
function about(){return `<div class="wrap page-shell reveal">${heading('THE STORY BEHIND THE ESCAPES','Built from a love<br><i>of going places.</i>','A personal approach to travel, rooted in a simple belief: every journey can bring a new experience.')}<div class="journey"><div class="portrait"><img src="assets/founder.webp" alt="Isaac ‘Saki’ Komane, Managing Director of Travel Saki"><div class="quote-box"><p>Same destination.<br>A new experience.</p><span>A PHILOSOPHY THAT STILL GUIDES US</span></div></div><div class="journey-copy"><span class="eyebrow">ISAAC ‘SAKI’ KOMANE · FOUNDER</span><h2>From planning for friends<br>to planning <i>for you.</i></h2><p>Before Travel Saki had a name, Saki was the person organising group trips. In 2018, he turned that passion into a company helping other people explore.</p><p>Today, Travel Saki arranges leisure, family, group and corporate journeys, bringing together accommodation, flights, transport and activities through a personal planning service.</p><p>From Southern Africa to island destinations and beyond, the aim is to create an experience that feels right for the people taking it.</p><a class="text-link" href="#plan">Start a conversation ↗</a></div></div><div class="about-principles"><div><span>✧</span><h3>Make it personal</h3><p>Start with your interests, your group and the experience you want to have.</p></div><div><span>⌖</span><h3>Bring it together</h3><p>Connect the stay, transport and experiences into a journey that makes sense.</p></div><div><span>↗</span><h3>Keep discovering</h3><p>Return to a favourite place or explore somewhere new. There’s always another story to find.</p></div></div><div class="testimonial"><span class="eyebrow">A TRAVELLER’S WORDS</span><blockquote>“Let me express my heartfelt appreciation for the outstanding service during our trip.”</blockquote><p>Dudu Mabaso</p><small>Testimonial published on Travel Saki’s website.</small></div></div>${cta()}`;}
function plan(params){const type=params.get('type')||'Holiday';const dest=params.get('destination')||'';const service=(params.get('service')||'')+(preferredMonth?'\nPreferred travel month: '+preferredMonth:'');const date=new Date().toISOString().slice(0,10);return `<div class="wrap page-shell reveal">${heading('LET’S MAKE IT YOURS','Your vision of a getaway.<br><i>Our place to begin.</i>','Tell us a little about the journey you have in mind. Review your enquiry, then choose to share it with the team by WhatsApp or email.')}<div class="form-layout"><aside class="form-aside"><span class="eyebrow">A HUMAN ON THE OTHER END</span><h2>Less guesswork.<br><i>More possibility.</i></h2><p>You don’t need a finished itinerary. Start with the feeling, the destination or the people you’d love to go with.</p><a href="tel:+27105009612">Call +27 10 500 9612 ↗</a><a href="mailto:bookings@travelsaki.co.za">bookings@travelsaki.co.za ↗</a><a href="https://wa.me/27614530438" target="_blank" rel="noopener noreferrer">Chat on WhatsApp ↗</a><p class="aside-note">Your enquiry is a starting point. Travel Saki will confirm availability, a quote and the booking arrangements directly with you.</p><p class="aside-note">Visiting us?<br>18 Craig Avenue, Malanshof<br>Randburg, Johannesburg, 2194<br><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=18+Craig+Avenue+Malanshof+Randburg" target="_blank" rel="noopener noreferrer">Get directions ↗</a></p></aside><form class="trip-form" id="trip-form"><div class="form-grid"><div class="field"><label for="full-name">Your full name *</label><input id="full-name" name="name" autocomplete="name" required maxlength="120" placeholder="Name and surname"></div><div class="field"><label for="email">Email address *</label><input id="email" name="email" autocomplete="email" type="email" required maxlength="160" placeholder="you@example.com"></div><div class="field"><label for="phone">Phone / WhatsApp number</label><input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="40" placeholder="+27"></div><div class="field"><label for="trip-type">What are you planning? *</label><select id="trip-type" name="type">${['Holiday','Couples getaway','Family holiday','Group getaway','Corporate travel','Transport'].map(t=>`<option ${type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field full"><label for="destination">Where would you like to go? *</label><input id="destination" name="destination" required value="${esc(dest)}" maxlength="200" placeholder="A destination, a route, or ‘help me choose’"></div><div class="field"><label for="depart">Preferred departure / pickup</label><input id="depart" name="departure" type="date" min="${date}"></div><div class="field"><label for="return">Return date</label><input id="return" name="return" type="date" min="${date}"></div><div class="field"><label for="adults">Adults *</label><input id="adults" name="adults" type="number" min="1" max="500" value="2" required></div><div class="field"><label for="children">Children</label><input id="children" name="children" type="number" min="0" max="100" value="0"></div><div class="field"><label for="budget">Estimated total budget</label><select id="budget" name="budget"><option>Help me work it out</option>Under R 10,000</option><option>R 10,000–R 25,000</option><option>R 25,000–R 50,000</option><option>R 50,000–R 100,000</option><option>R 100,000+</option></select></div><div class="field"><label for="style">Your travel style</label><select id="style" name="style"><option>A little of everything</option>Beach & islands</option><option>Safari & nature</option><option>Adventure</option><option>City & culture</option><option>Business & events</option></select></div><div class="field full"><label for="details">What would make this journey special?</label><textarea id="details" name="details" maxlength="2000" placeholder="Must-do experiences, a celebration, children’s ages, accessibility needs, or transport pickup and drop-off details">${esc(service)}</textarea></div></div><label class="checkbox"><input type="checkbox" required name="consent"><span>I agree to share these details with Travel Saki to discuss my enquiry. <a href="#privacy" style="text-decoration:underline">How your information is handled</a></span></label><div class="form-actions"><button class="button" type="submit">Review my enquiry ↗</button></div><p class="form-note">Reviewing does not send anything. You choose WhatsApp or your email app in the next step.</p><div id="enquiry-preview"></div></form></div><div class="faq"><span class="eyebrow">A FEW THINGS YOU MAY BE WONDERING</span>${[['Can you tailor a trip for my group?','Yes. Travel Saki offers customised journeys and group bookings. Share your group size, preferred dates, destinations and the experiences you have in mind.'],['Can I enquire before choosing a destination?','Absolutely. Write “help me choose” in the destination field and tell the team about your travel style and budget.'],['Does this enquiry confirm a booking?','No. Your enquiry starts a conversation. Dates, availability, the final quote, payment arrangements and confirmation must be agreed directly with Travel Saki.'],['Can I arrange transport only?','Yes. Select Transport and include your pickup point, destination, preferred time, number of passengers and luggage needs.']].map(f=>`<details><summary>${f[0]}</summary><p>${f[1]}</p></details>`).join('')}</div></div>`;}
function legal(kind){return `<div class="wrap page-shell legal reveal">${kind==='privacy'?heading('YOUR INFORMATION','Privacy &<br><i>your enquiry.</i>','How this website handles the information you choose to share.')+`<h2>Trip enquiries</h2><p>The enquiry form builds a message in your browser. It does not submit details to a website database. When you select WhatsApp or email, your details are passed to that service so you can send them to Travel Saki.</p><p>You can edit the message before sending. Only share information needed to plan your trip. Do not include payment card details, passwords or identity document numbers.</p><h2>Your shortlist</h2><p>Saved tour IDs are kept in local storage on your device so your shortlist remains available when you return. You can remove saved tours with the heart button or clear your browser’s site data.</p><h2>External services</h2><p>WhatsApp, Instagram, Facebook, Google Maps and your email provider have their own privacy practices. Fonts may load from Google Fonts. External links open the relevant provider’s website or app.</p><h2>Contact Travel Saki</h2><p>For enquiries about information you send to the business, contact <a class="text-link" href="mailto:info@travelsaki.co.za">info@travelsaki.co.za</a>.</p>`:heading('BEFORE YOU TRAVEL','A few details<br><i>worth knowing.</i>','This site helps you discover experiences and enquire. Your booking is arranged directly with Travel Saki.')+`<h2>Published prices and dates</h2><p>The catalogue uses package prices published by Travel Saki. They are reference prices, not a live quote. Several published departure dates have already passed. Ask the team for current departure options, pricing, availability and a confirmed itinerary.</p><h2>What is included</h2><p>Package details summarise the operator’s published descriptions. Activities marked at your own cost remain extra. Confirm flights, accommodation, transport, meals, activities, taxes and any exclusions before paying.</p><h2>Confirming a booking</h2><p>An enquiry or a saved experience does not reserve a place. Ask Travel Saki for the written quote, payment schedule, cancellation terms and booking confirmation that apply to your trip. This website does not collect payments.</p><h2>Travel documents and requirements</h2><p>For cross-border trips, ask the team what documentation and arrangements you need. Requirements depend on your nationality, route, traveller ages and dates. Confirm applicable official requirements before departure.</p><h2>Need a hand?</h2><p><a class="text-link" href="#plan">Start an enquiry ↗</a> or call <a href="tel:+27105009612">+27 10 500 9612</a>.</p>`}</div>`;}
function showDetail(id){const t=tours.find(x=>x.id===id);if(!t)return;$('#detail-content').innerHTML=`<div class="detail-hero"><img src="assets/package-${t.image}.webp" alt="${esc(t.title)}"></div><div class="detail-body"><span class="eyebrow">${esc(t.location)}</span><h2 id="detail-title">${esc(t.title)}</h2><p>${t.description}</p><div class="detail-meta"><div class="price">${currency(t.price)}<small>Published package price · confirm current quote</small></div><span style="font-size:12px">${esc(t.date)}</span></div>${t.included.length?`<h3>Published package highlights</h3><ul>${t.included.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p>${esc(t.note)}</p><div class="form-actions"><a class="button" href="#plan?destination=${encodeURIComponent(t.location)}&service=${encodeURIComponent('I’m interested in '+t.title+' (published price '+currency(t.price)+'). Please confirm upcoming dates, pricing and availability.')}" data-close-dialog>Enquire about this trip ↗</a><button class="button outline" data-save="${t.id}" aria-pressed="${saved.includes(t.id)}">${saved.includes(t.id)?'♥':'♡'} Save to shortlist</button></div><a class="detail-source" href="https://travelsakisa.co.za/product/${t.source}/" target="_blank" rel="noopener noreferrer">View the operator’s published package ↗</a></div>`;$('#detail-dialog').showModal();}
function reviewEnquiry(e){e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const d=Object.fromEntries(new FormData(form));if(d.departure && d.return && d.return<d.departure){$('#return').setCustomValidity('Return date must be on or after departure.');$('#return').reportValidity();return;}const text=`Hi Travel Saki, I’d like to enquire about a trip.\n\nName: ${d.name}\nEmail: ${d.email}\nPhone: ${d.phone||'Not provided'}\nTrip type: ${d.type}\nDestination / route: ${d.destination}\nDeparture / pickup: ${d.departure||'Flexible'}\nReturn: ${d.return||'Flexible'}\nTravellers: ${d.adults} adult(s), ${d.children||0} child(ren)\nEstimated total budget: ${d.budget}\nTravel style: ${d.style}\n\nDetails: ${d.details||'Please help me shape the itinerary.'}\n\nPlease confirm current options, pricing and availability.`;$('#enquiry-preview').innerHTML=`<div class="enquiry-preview"><span class="eyebrow">READY WHEN YOU ARE</span><h3>Here’s your enquiry.</h3><pre>${esc(text)}</pre><div class="form-actions"><a class="button" href="https://wa.me/27614530438?text=${encodeURIComponent(text)}" target="_blank" rel="noopener noreferrer">Continue in WhatsApp ↗</a><a class="button outline" href="mailto:bookings@travelsaki.co.za?subject=${encodeURIComponent('Travel enquiry — '+d.destination)}&body=${encodeURIComponent(text)}">Open my email app ↗</a><button type="button" class="button outline" id="copy-enquiry">Copy enquiry</button></div><p class="form-note">Your enquiry has not been sent. Complete sending in WhatsApp or your email app.</p></div>`;$('#copy-enquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(text);toast('Enquiry copied');}catch{toast('Select the enquiry text above to copy it.');}});$('#enquiry-preview').scrollIntoView({behavior:'smooth',block:'nearest'});}
function route(){const raw=location.hash.slice(1)||'home';const [page,query='']=raw.split('?');const params=new URLSearchParams(query);$('#detail-dialog').close();$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');document.querySelectorAll('nav>a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));const names={home:'Experience Paradise on Earth',tours:'Our Travel Experiences',destinations:'Destinations',transport:'Transport & Transfers',about:'Our Story',plan:'Plan Your Trip',privacy:'Privacy','booking-notes':'Booking Information'};document.title=`Travel Saki | ${names[page]||names.home}`;if(page==='tours'){if(params.has('destination')||params.has('style'))currentFilters.savedOnly=false;if(params.has('month'))preferredMonth=params.get('month');if(params.has('destination'))currentFilters.query=params.get('destination');if(params.has('style'))currentFilters.category=categories.includes(params.get('style'))?params.get('style'):'All experiences';main.innerHTML=toursPage();updateTours();$('#tour-query').addEventListener('input',e=>{currentFilters.query=e.target.value;updateTours();});$('#tour-category').addEventListener('change',e=>{currentFilters.category=e.target.value;updateTours();});$('#tour-sort').addEventListener('change',e=>{currentFilters.sort=e.target.value;updateTours();});$('#saved-filter').addEventListener('click',e=>{currentFilters.savedOnly=!currentFilters.savedOnly;e.currentTarget.setAttribute('aria-pressed',currentFilters.savedOnly);e.currentTarget.textContent=currentFilters.savedOnly?'Show all experiences':'My shortlist ♡';updateTours();});}else if(page==='destinations')main.innerHTML=destinations();else if(page==='transport')main.innerHTML=transport();else if(page==='about')main.innerHTML=about();else if(page==='plan'){main.innerHTML=plan(params);$('#trip-form').addEventListener('submit',reviewEnquiry);const dep=$('#depart'),ret=$('#return');[dep,ret].forEach(el=>el.addEventListener('input',()=>{ret.setCustomValidity('');ret.min=dep.value||new Date().toISOString().slice(0,10);$('#enquiry-preview').innerHTML='';}));$('#trip-form').addEventListener('input',()=>{$('#enquiry-preview').innerHTML='';});}else if(page==='privacy'||page==='booking-notes')main.innerHTML=legal(page);else{main.innerHTML=home();$('#discovery-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);currentFilters.savedOnly=false;location.hash='tours?destination='+encodeURIComponent(d.get('destination'))+'&style='+encodeURIComponent(d.get('style'))+'&month='+encodeURIComponent(d.get('month')||'');if(d.get('month'))toast('Preferred month: '+d.get('month')+'. Confirm available dates with the team.');});}window.scrollTo(0,0);}
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){saveTour(save.dataset.save);return;}const detail=e.target.closest('[data-detail]');if(detail){showDetail(detail.dataset.detail);return;}const ht=e.target.closest('[data-home-category]');if(ht){homeCategory=ht.dataset.homeCategory;$('#home-tour-grid').innerHTML=homeTourCards();document.querySelectorAll('[data-home-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.homeCategory===homeCategory));return;}const exp=e.target.closest('[data-experience]');if(exp){currentFilters.query='';currentFilters.savedOnly=false;location.hash='tours?style='+encodeURIComponent(exp.dataset.experience);return;}if(e.target.closest('[data-reset]')){currentFilters={query:'',category:'All experiences',sort:'featured',savedOnly:false};if(location.hash==='#tours')route();else location.hash='tours';}if(e.target.closest('[data-close-dialog]'))$('#detail-dialog').close();});
$('.dialog-close').addEventListener('click',()=>$('#detail-dialog').close());$('#detail-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});$('.menu-toggle').addEventListener('click',e=>{const open=$('#navigation').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);e.currentTarget.setAttribute('aria-label',open?'Close navigation':'Open navigation');});window.addEventListener('hashchange',route);$('#year').textContent=new Date().getFullYear();route();
